MERGE INTO SCM_MGR.SCM_ADM_MNU_BTN_MPG_M T
USING (SELECT 'SCP0016' MNU_ID, 'main' SHT_NM, 'MEASURE_SELECT' MNU_BTN_CD, NULL API_ID, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'SCP0016' MNU_ID, 'main' SHT_NM, 'SEARCH' MNU_BTN_CD, 'P_SCP0016_GET' API_ID, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'SCP0016' MNU_ID, 'spreadTitle' SHT_NM, 'SEARCH' MNU_BTN_CD, 'SCP0009_SHEET_CALENDAR_3SPAN_GET' API_ID, 'Y' USE_YN FROM DUAL
       UNION ALL SELECT 'SCP0016' MNU_ID, 'spreadTitleIso' SHT_NM, 'SEARCH' MNU_BTN_CD, 'SCP0009_SHEET_CALENDAR_3SPAN_ISO_GET' API_ID, 'Y' USE_YN FROM DUAL) S
   ON (NVL(TO_CHAR(T.MNU_ID), '~') = NVL(TO_CHAR(S.MNU_ID), '~') AND NVL(TO_CHAR(T.SHT_NM), '~') = NVL(TO_CHAR(S.SHT_NM), '~') AND NVL(TO_CHAR(T.MNU_BTN_CD), '~') = NVL(TO_CHAR(S.MNU_BTN_CD), '~'))
 WHEN MATCHED THEN UPDATE SET T.API_ID = S.API_ID, T.USE_YN = S.USE_YN, T.LAST_UPDATED_BY = 'admin', T.LAST_UPDATE_DATE = SYSDATE
      WHERE DECODE(T.API_ID, S.API_ID, 0, 1) = 1 OR DECODE(T.USE_YN, S.USE_YN, 0, 1) = 1
 WHEN NOT MATCHED THEN INSERT (MNU_ID, SHT_NM, MNU_BTN_CD, API_ID, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
      VALUES (S.MNU_ID, S.SHT_NM, S.MNU_BTN_CD, S.API_ID, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE);

