  FROM (SELECT 'BIZ_TYPE' SQL_ID, 'ALL' MDU_DIVS_CD, '[공통] AS-IS UP_FX_GetCommonDataList @Code=''BIZ_TYPE''' SQL_NM, 'select SEGMENT1 as code , SEGMENT2 as name from SCM_ADM_LOOKUP_MASTER_DETAIL where LOOKUP_TYPE =''BIZ_TYPE_BPMS'' order by DISPLAY_SEQ' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
