INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'SYSTEM' SQL_ID, 'ALL' MDU_DIVS_CD, 'Lookup System' SQL_NM, '    SELECT  T1.SEGMENT1 CODE, T1.SEGMENT2 NAME' || CHR(13) || CHR(10) || '     FROM  SCM_ADM_LOOKUP_MASTER_DETAIL T1' || CHR(13) || CHR(10) || '    WHERE  1=1' || CHR(13) || CHR(10) || '      AND  T1.LOOKUP_TYPE = ''SYSTEM''' || CHR(13) || CHR(10) || '      AND  T1.VALID_YN = ''Y''' || CHR(13) || CHR(10) || ' ORDER BY  T1.DISPLAY_SEQ' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));
INSERT INTO SCM_MGR.SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
SELECT S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, 'admin', SYSDATE, 'admin', SYSDATE
  FROM (SELECT 'WaterfallVer_FG2_SCP' SQL_ID, 'ALL' MDU_DIVS_CD, '[SCP] AS-IS UP_FX_GetCommonDataList_SCP @Code=''WaterfallVer_FG2''' SQL_NM, 'SELECT ''SP_W_'' || A.PLAN_START_YYYYMMDD CODE , CASE WHEN FP_TARGET_YN = ''Y'' THEN ''SP_W_'' || A.PLAN_START_YYYYMMDD || '' ('' || B.WEEK_NAME || '')'' ELSE ''SP_W_'' || A.PLAN_START_YYYYMMDD || '' ('' || B.WEEK_NAME || '')'' || '' (No Plan)'' END NAME FROM SCP_PLAN_VERSION_V A INNER JOIN SCM_SYS_CALENDAR_M B ON A.PLAN_START_YYYYMMDD = B.BASIS_YYYYMMDD LEFT JOIN ( SELECT DIVISION_ID , PLAN_START_YYYYMMDD , FP_TARGET_YN , MRP_TARGET_YN , DM_RTF_YN FROM SCP_PLN_INTERFACE_YN WHERE 1=1 AND DIVISION_ID IN (SELECT Value FROM FN_SplitString(@divisionId,'','')) ) C ON A.PLAN_START_YYYYMMDD = C.PLAN_START_YYYYMMDD AND A.DIVISION_ID = C.DIVISION_ID WHERE 1=1 AND A.DIVISION_ID= @divisionId AND PLAN_TYPE =''FN'' AND CONFIRM_FLAG =''Y'' ORDER BY UPPER(A.PLAN_START_YYYYMMDD) DESC FETCH FIRST 10 ROWS ONLY' SQL_DTL_CTN, 'Y' USE_YN FROM DUAL) S
 WHERE NOT EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_CMBO_SQL_M T WHERE NVL(TO_CHAR(T.SQL_ID), '~') = NVL(TO_CHAR(S.SQL_ID), '~') AND NVL(TO_CHAR(T.MDU_DIVS_CD), '~') = NVL(TO_CHAR(S.MDU_DIVS_CD), '~'));

COMMIT;
